import click
from click.testing import CliRunner


def test_deprecated_command_without_help_formatting():
    @click.command(deprecated=True)
    def cli():
        pass

    runner = CliRunner()
    result = runner.invoke(cli, ["--help"])
    assert result.exit_code == 0
    assert "  (DEPRECATED)\n" in result.output
